package com.takodu.api.shared.domain.model.valueobjects;

import java.util.UUID;

/**
 * One user action, generated by the client and resent unchanged on every retry, so the action takes effect once.
 *
 * @param value the UUID from the {@code Idempotency-Key} header
 */
public record IdempotencyKey(UUID value) {
    public IdempotencyKey {
        if (value == null) throw new IllegalArgumentException("Idempotency-Key header is required");
    }
}
